<section class="mb-6 flex flex-col justify-between gap-4 sm:flex-row sm:items-start"><div><a href="<?= e(url('/daftar-ulang')) ?>" class="text-sm font-semibold text-primary hover:underline">← Daftar ulang</a><h1 class="mt-3 text-2xl font-bold text-slate-900">Detail Pengajuan</h1><p class="mt-1 font-mono text-sm text-slate-500"><?= e($item['no_registrasi']) ?></p></div><span class="badge badge-<?= strtolower($item['status_verifikasi']) ?> self-start"><?= e($item['status_verifikasi']) ?></span></section><section class="grid gap-6 lg:grid-cols-3"><article class="rounded-2xl bg-white p-6 shadow-card lg:col-span-2"><h2 class="font-bold text-slate-900">Informasi Pengajuan</h2><dl class="mt-6 grid gap-5 sm:grid-cols-2"><div><dt class="detail-label">Pelanggan</dt><dd class="detail-value"><a href="<?= e(url('/pelanggan/' . rawurlencode($item['npa']))) ?>" class="text-primary hover:underline"><?= e($item['nama_pelanggan']) ?></a></dd></div><div><dt class="detail-label">NPA</dt><dd class="detail-value font-mono"><?= e($item['npa']) ?></dd></div><div class="sm:col-span-2"><dt class="detail-label">Alamat</dt><dd class="detail-value"><?= e($item['alamat']) ?></dd></div><div><dt class="detail-label">Tanggal Permohonan</dt><dd class="detail-value"><?= e(formatTanggalWaktu($item['tgl_permohonan'])) ?></dd></div><div><dt class="detail-label">Biaya Daftar Ulang</dt><dd class="detail-value"><?= e(formatRupiah($item['biaya_daftar_ulang'])) ?></dd></div><div><dt class="detail-label">Bukti Pelunasan</dt><dd class="detail-value"><?php if ($item['bukti_lunas']): ?><a class="font-semibold text-primary hover:underline" target="_blank" rel="noopener" href="<?= e(url('/daftar-ulang/' . rawurlencode($item['no_registrasi']) . '/bukti')) ?>">Lihat bukti lunas ↗</a><?php else: ?><span class="text-slate-500">Belum diunggah</span><?php endif; ?></dd></div><div><dt class="detail-label">Diverifikasi oleh</dt><dd class="detail-value"><?= e($item['verifier'] ?: 'Belum diverifikasi') ?></dd></div><div class="sm:col-span-2"><dt class="detail-label">Keterangan</dt><dd class="detail-value"><?= e($item['keterangan'] ?: '—') ?></dd></div><?php if ($item['tgl_verifikasi']): ?><div><dt class="detail-label">Tanggal Verifikasi</dt><dd class="detail-value"><?= e(formatTanggalWaktu($item['tgl_verifikasi'])) ?></dd></div><?php endif; ?></dl></article><aside class="rounded-2xl bg-white p-6 shadow-card"><h2 class="font-bold text-slate-900">Tindakan Verifikasi</h2><?php if (Auth::isAdmin() && $item['status_verifikasi'] === 'Pending'): ?><p class="mt-2 text-sm leading-6 text-slate-500">Pastikan bukti pelunasan dan kelengkapan pengajuan telah diperiksa.</p><form method="post" action="<?= e(url('/daftar-ulang/' . rawurlencode($item['no_registrasi']) . '/approve')) ?>" class="mt-5 space-y-3"><?= csrf_field() ?><label class="flex cursor-pointer gap-3 rounded-xl bg-blue-50 p-3 text-sm text-primary"><input type="checkbox" name="aktifkan_pelanggan" value="1" checked class="mt-0.5">Aktifkan kembali status pelanggan setelah disetujui.</label><button class="w-full rounded-xl bg-success px-4 py-3 text-sm font-bold text-white hover:bg-emerald-700" data-confirm="Setujui pengajuan ini dan aktifkan kembali pelanggan?">Setujui Pengajuan</button></form><form method="post" action="<?= e(url('/daftar-ulang/' . rawurlencode($item['no_registrasi']) . '/reject')) ?>" class="mt-3" data-confirm="Tolak pengajuan daftar ulang ini?"> <?= csrf_field() ?><button class="w-full rounded-xl border border-danger px-4 py-3 text-sm font-bold text-danger hover:bg-red-50">Tolak Pengajuan</button></form><?php elseif ($item['status_verifikasi'] === 'Pending'): ?><p class="mt-3 rounded-xl bg-amber-50 p-4 text-sm leading-6 text-warning">Menunggu verifikasi Admin Hublang. Pimpinan memiliki akses lihat saja.</p><?php else: ?><p class="mt-3 rounded-xl <?= $item['status_verifikasi'] === 'Disetujui' ? 'bg-emerald-50 text-success' : 'bg-red-50 text-danger' ?> p-4 text-sm leading-6">Pengajuan telah <?= e(strtolower($item['status_verifikasi'])) ?>. Riwayat tetap tersimpan untuk audit.</p><?php endif; ?></aside></section>
